-- ATI: thay 2 sản phẩm giữ chỗ bằng 2 sản phẩm Staywell lấy từ Shopee (dùng cho D1 đã chạy seed cũ).
-- D1 mới đã có sản phẩm từ products.csv nên INSERT OR IGNORE bỏ qua.
DELETE FROM products WHERE sku IN ('ATI-001', 'ATI-002');
INSERT OR IGNORE INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('STW-GINGER', 'nuoc-gung-ginger-shot-staywell-hop-12-goi-x-20g', 'Nước gừng Ginger Shot Staywell', 'Hộp 12 gói x 20g', 'staywell', 'main', 100000, NULL, NULL, NULL, 100, 'https://down-vn.img.susercontent.com/file/vn-11134207-81ztc-mpwfab8id79q27', 'https://down-vn.img.susercontent.com/file/vn-11134207-81ztc-mpwfab8id79q27', 'Nước gừng tinh chất dạng gói uống liền, kết hợp gừng, nghệ (curcumin), táo đỏ, chanh và vitamin C, D3. Hỗ trợ tiêu hoá và tăng sức đề kháng mỗi ngày.', 'Ginger Shot Staywell kết hợp các thành phần tự nhiên quen thuộc: gừng, nghệ, táo đỏ, chanh, cà phê xanh, bổ sung vitamin C và D3. Sản xuất tại nhà máy đạt tiêu chuẩn ISO và HACCP tại Việt Nam. Sản phẩm này không phải là thuốc và không có tác dụng thay thế thuốc chữa bệnh.', '["Hỗ trợ tiêu hoá, giảm cảm giác đầy hơi, khó tiêu","Hỗ trợ tăng sức đề kháng","Bổ sung vitamin C từ táo đỏ và vitamin D3","Gói 20g tiện mang theo, uống liền hoặc pha loãng"]', 'Mỗi ngày dùng 1 đến 2 gói, trước hoặc sau khi ăn. Uống trực tiếp hoặc pha loãng với 100ml nước lọc, có thể thêm đá. Bảo quản nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp. Hạn sử dụng 18 tháng.', 'Bột gừng (120mg), Nano Curcumin, Maxicuma (Curcumin 40%), bột táo đỏ, bột cà phê xanh, bột chiết xuất táo đỏ (167mg vitamin C), vitamin D3, chất tạo ngọt tự nhiên, bột chanh (267mg).', '12 gói x 20g', '["Mua 1 tặng 1"]', '[]', NULL, 'https://shopee.vn/product/1728219880/57812819041', NULL, 'Nước gừng tinh chất dạng gói uống liền, kết hợp gừng, nghệ (curcumin), táo đỏ, chanh và vitamin C, D3. Hỗ trợ tiêu hoá và tăng sức đề kháng mỗi ngày.', 300, 15, 10, 6, 0, 1);
INSERT OR IGNORE INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, shopee_url, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('STW-RAUCU-2', 'bot-rau-cu-staywell-combo-2-hop-15-goi-x-3g', 'Bột rau củ Staywell', 'Combo 2 hộp · 15 gói x 3g', 'staywell', 'main', 100000, NULL, NULL, NULL, 100, 'https://down-vn.img.susercontent.com/file/vn-11134207-81ztc-mn5dfpsz826d77', 'https://down-vn.img.susercontent.com/file/vn-11134207-81ztc-mn5dfpsz826d77', 'Bột rau cần tây, cải kale, bó xôi, diếp cá, tía tô, cà rốt sấy lạnh, dạng gói pha nhanh. Cách đơn giản để thêm rau mỗi ngày cho người bận rộn.', 'Bột rau củ Staywell giúp bổ sung rau củ một cách tiện lợi khi việc ăn đủ rau mỗi ngày trở nên khó khăn. Thành phần phối trộn cân đối, vị dễ uống, ứng dụng công nghệ sấy lạnh, phát triển từ nông sản Việt Nam. Sản phẩm này không phải là thuốc và không có tác dụng thay thế thuốc chữa bệnh.', '["Bổ sung chất xơ từ rau, hỗ trợ tiêu hoá","Bổ sung vitamin và khoáng chất từ rau xanh","Tạo cảm giác no lâu, hỗ trợ kiểm soát khẩu phần","Công nghệ sấy lạnh, gói 3g tiện dùng"]', 'Đổ 1 gói vào ly, thêm 200 đến 250ml nước lọc (150 đến 180ml nếu thích đậm vị), khuấy đều. Dùng 3 đến 4 gói mỗi ngày. Ngon hơn khi uống với đá, có thể pha cùng nước ép hoặc sinh tố. Người dị ứng với các loại rau trong thành phần nên tham khảo ý kiến trước khi dùng.', 'Cần tây (19%), cải kale (15,2%), bó xôi (15,2%), diếp cá (6,65%), tía tô (6,65%), cà rốt (6,65%), chất xơ, mật ong.', '2 hộp x 15 gói x 3g', '["Mua 2 tặng 2"]', '[]', NULL, 'https://shopee.vn/product/1728219880/56308990956', NULL, 'Bột rau cần tây, cải kale, bó xôi, diếp cá, tía tô, cà rốt sấy lạnh, dạng gói pha nhanh. Cách đơn giản để thêm rau mỗi ngày cho người bận rộn.', 250, 15, 10, 8, 0, 2);
